#include <bits/stdc++.h>
#define LIMIT 30
#define MODUL 1000000007
using namespace std;

long long total;
int base, matrix[65][35][35], remainders[65], count, tempG[35][35], resultA[35], resultB[35];

inline int subtractMod(int x, int y) {
    return (x < base) ? (x - y + base) % base : (x - y + base) % base;
}

int main() {
    cin >> total >> base;
    for (long long t = total; t; t /= base) remainders[++count] = t % base;
    for (int i = 1; i <= base; ++i) matrix[1][i][i] = 1;
    for (int i = 0; i <= base; ++i) matrix[1][0][i] = 1;
    for (int step = 2; step <= count; ++step) {
        for (int j = 0; j <= base; ++j) matrix[step][j][j] = 1;
        for (int j = 0; j < base; ++j) {
            for (int a = 0; a <= base; ++a)
                for (int b = 0; b <= base; ++b)
                    for (int c = 0; c <= base; ++c)
                        tempG[a][c] = (tempG[a][c] + (long long)matrix[step - 1][subtractMod(a, j)][subtractMod(b, j)] * matrix[step][b][c]) % MODUL;
            for (int a = 0; a <= base; ++a)
                for (int b = 0; b <= base; ++b)
                    matrix[step][a][b] = tempG[a][b], tempG[a][b] = 0;
        }
    }
    for (int i = 0; i <= base; ++i) resultA[i] = 1;
    for (int i = 1; i <= count; ++i) {
        int sumS = 0;
        for (int j = i + 1; j <= count; ++j) sumS = (sumS + remainders[j]) % base;
        for (; remainders[i]; --remainders[i]) {
            int decVal = (sumS + remainders[i]) % base;
            for (int a = 0; a <= base; ++a)
                for (int b = 0; b <= base; ++b)
                    resultB[b] = (resultB[b] + (long long)resultA[a] * matrix[i][subtractMod(a, decVal)][subtractMod(b, decVal)]) % MODUL;
            for (int a = 0; a <= base; ++a) resultA[a] = resultB[a], resultB[a] = 0;
        }
    }
    cout << resultA[base] << "\n";
    return 0;
}
